+        errorMessage = null;
+        try
+        {
+            tasks = await TaskService.GetAllTasksAsync();
+        }
+        catch (Exception ex)
+        {
+            errorMessage = $"Failed to load tasks: {ex.Message}";
+        }
+        finally
+        {
+            isLoading = false;
+        }
+    }
+
+    private List<TaskItem> GetFilteredTasksForColumn(string status)
+    {
+        var columnTasks = tasks.Where(t => t.Status == status);
+        if (!string.IsNullOrWhiteSpace(searchTerm))
+        {
+            columnTasks = columnTasks.Where(t =>
+                t.Title.Contains(searchTerm, StringComparison.OrdinalIgnoreCase));
+        }
+        return columnTasks.ToList();
+    }
+
+    private void HandleSearchChanged(string term)
+    {
+        searchTerm = term;
+    }
+
+    private async Task HandleMoveTask(int columnIndex, int taskId, BoardColumn.MoveDirection direction)
+    {
+        var targetIndex = direction == BoardColumn.MoveDirection.Left
+            ? columnIndex - 1
+            : columnIndex + 1;
+
+        if (targetIndex < 0 || targetIndex >= columns.Length)
+            return;
+
+        var newStatus = columns[targetIndex];
+        await TaskService.UpdateTaskStatusAsync(taskId, newStatus);
+
+        var oldTask = tasks.First(t => t.Id == taskId);
+        var updatedTask = oldTask with { Status = newStatus };
+        tasks = tasks.Select(t => t.Id == taskId ? updatedTask : t).ToList();
+    }
+
+    private void HandleTaskCreated(TaskItem task)
+    {
+        tasks.Add(task);
+    }
+}
+

